        .slide-number { position: absolute; top: var(--slide-padding); right: var(--slide-padding); font-family: var(--font-display); font-size: clamp(1.5rem, 3vw, 2rem); font-weight: 800; color: rgba(255,255,255,0.1); }
        .logo-mark { position: absolute; bottom: var(--slide-padding); right: var(--slide-padding); font-size: 1.2rem; font-weight: 800; color: rgba(255,255,255,0.2); }

        .highlight { color: #FFFFFF; font-weight: 700; }
        .stat-box { background: rgba(243, 128, 32, 0.1); border-left: 4px solid var(--accent); padding: 1.5rem; border-radius: 0 8px 8px 0; margin-top: 1rem; }
        .stat-number { font-size: clamp(2rem, 4vw, 3rem); font-weight: 800; color: var(--accent); line-height: 1; margin-bottom: 0.5rem; }

        .reveal { opacity: 0; transform: translateY(30px); transition: opacity var(--duration-normal) var(--ease-out-expo), transform var(--duration-normal) var(--ease-out-expo); }
        .slide.visible .reveal { opacity: 1; transform: translateY(0); }
        .reveal:nth-child(1) { transition-delay: 0.1s; }
        .reveal:nth-child(2) { transition-delay: 0.2s; }
